package com.householdfinance.finance.adapter.in.rest;import static com.householdfinance.finance.adapter.in.rest.FinanceDtos.*;import com.householdfinance.finance.application.port.in.*;import com.householdfinance.finance.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/households/{householdId}")public class CardCategoryController{final CreditCardUseCase cards;final CategoryUseCase categories;CardCategoryController(CreditCardUseCase c,CategoryUseCase k){cards=c;categories=k;}UUID u(Authentication a){return UUID.fromString(a.getName());}@PostMapping("/cards")ResponseEntity<Map<String,Object>> card(Authentication a,@PathVariable UUID householdId,@Valid @RequestBody AccountRequest x){var c=cards.issue(u(a),new HouseholdId(householdId),x.name(),x.openingBalance().domain());return ResponseEntity.status(201).body(Map.of("id",c.id().toString(),"name",c.name(),"creditLimit",c.creditLimit()));}@PostMapping("/categories")ResponseEntity<Map<String,String>> category(Authentication a,@PathVariable UUID householdId,@Valid @RequestBody HouseholdRequest x){var c=categories.create(u(a),new HouseholdId(householdId),x.name());return ResponseEntity.status(201).body(Map.of("id",c.id().toString(),"name",c.name()));}}
